def compute(vars):
    gain_on_land_sales = vars["v1"]
    gain_on_ownership_interests = vars["v2"]

    total_gain_thousand = gain_on_land_sales + gain_on_ownership_interests
    total_gain_million = total_gain_thousand / 1000

    return {
        "value": total_gain_million,
        "trace": {
            "gain_on_land_sales_thousand": gain_on_land_sales,
            "gain_on_ownership_interests_thousand": gain_on_ownership_interests,
            "total_gain_thousand": total_gain_thousand,
            "conversion": "thousand to million by dividing by 1000",
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
